<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,loadWorkspaces,loadData,notify} from '../state'
const route=useRoute(),router=useRouter(),busy=ref(false),error=ref(''),success=ref(''),email=ref(''),password=ref(''),name=ref(''),forgot=ref(false),invitation=ref<any>(null)
const inviteToken=ref(sessionStorage.getItem('sd_invite'))
const register=computed(()=>route.path==='/register'),reset=computed(()=>route.path==='/reset'),verify=computed(()=>route.path==='/verify'),invite=computed(()=>route.path==='/invite')
watch(()=>route.path,()=>{error.value='';success.value='';forgot.value=false})
async function submit(){busy.value=true;error.value='';sessionStorage.removeItem('sd_tour');try{if(forgot.value){await api('/auth/reset-request',{method:'POST',body:{email:email.value}});success.value=t('If an account exists, a password reset link has been queued for delivery.','Если аккаунт существует, письмо со ссылкой на сброс пароля поставлено в очередь.');return}if(reset.value){state.user=await api('/auth/reset',{method:'POST',body:{token:route.query.token,password:password.value}})}else{state.user=await api('/auth/'+(register.value?'register':'login'),{method:'POST',body:{email:email.value,password:password.value,name:name.value,invite_token:sessionStorage.getItem('sd_invite')||''}})}state.workspace=null;state.workspaces=[];state.events=[];if(!state.user.verified){router.push('/check-email');return}await loadWorkspaces();await loadData();const token=sessionStorage.getItem('sd_invite');if(token){router.push('/invite?token='+token)}else{router.push(state.workspace?.onboarded?'/overview':'/onboarding')}}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function accept(){busy.value=true;try{const r=await api('/invites/'+route.query.token+'/accept',{method:'POST'});sessionStorage.removeItem('sd_invite');await loadWorkspaces(r.workspace_id);await loadData();router.push('/overview')}catch(e:any){error.value=e.message}finally{busy.value=false}}
watch(()=>[route.path,route.query.token],async([path,rawToken])=>{
 const token=String(rawToken||'')
 if(path==='/invite'&&token){
  sessionStorage.setItem('sd_invite',token);inviteToken.value=token
  try{invitation.value=await api('/invites/'+token)}catch(e:any){error.value=e.message}
 }
 if(path==='/verify'){
  busy.value=true;sessionStorage.removeItem('sd_tour');inviteToken.value=sessionStorage.getItem('sd_invite')
  try{const r=await api('/auth/verify',{method:'POST',body:{token}});state.user=r.user;if(r.invite_token){inviteToken.value=r.invite_token;sessionStorage.setItem('sd_invite',r.invite_token)}await loadWorkspaces();await loadData();success.value=t('Email confirmed. You can now receive briefs and invite your team.','Почта подтверждена. Теперь можно получать сводки и приглашать команду.')}
  catch(e:any){error.value=e.message}finally{busy.value=false}
 }
},{immediate:true})
</script>
<template><div class="auth-layout"><section class="auth-editorial"><span class="eyebrow">{{t('A CLEARER VIEW, EVERY DAY','ЯСНАЯ КАРТИНА КАЖДЫЙ ДЕНЬ')}}</span><h1>{{t('Good decisions','Хорошие решения')}}<br>{{t('start with','начинаются')}}<br><em>{{t('the right context.','с контекста.')}}</em></h1><p>{{t('Your company is unique. Your business intelligence should be, too.','Ваша компания уникальна. Аналитика для неё тоже должна быть персональной.')}}</p><div class="auth-quote"><Icon name="Quote" :size="28"/><p>{{t('What happened is only the beginning. The better question is: what does it change for us?','Что произошло — лишь начало. Важнее понять: что это меняет для нас?')}}</p><span>THE SIGNALDESK APPROACH</span></div></section><section class="auth-card">
  <span class="auth-icon"><Icon :name="verify?'MailCheck':invite?'Users':'ArrowUpRight'" :size="24"/></span>
  <template v-if="verify"><h2>{{t('Confirm your email','Подтверждение почты')}}</h2><div v-if="busy" class="row gap-sm"><Icon name="LoaderCircle" class="spin"/>{{t('Verifying your link…','Проверяем ссылку…')}}</div><p v-if="success" class="notice success-notice">{{success}}</p><p v-if="error" class="notice error-notice" role="alert">{{error}}</p><RouterLink :to="state.user?(inviteToken?'/invite?token='+inviteToken:state.workspace?.onboarded?'/overview':'/onboarding'):'/login'" class="btn primary full">{{t('Continue to SignalDesk','Продолжить')}}</RouterLink></template>
  <template v-else-if="invite"><h2>{{t('A seat at the table','Место в команде')}}</h2><template v-if="invitation"><p>{{t('You are invited to','Вас пригласили в')}} <strong>{{invitation.workspace}}</strong></p><p class="muted">{{t('Role','Роль')}}: {{invitation.role}} · {{invitation.email_hint}}</p><button v-if="state.user" class="btn primary full" @click="accept" :disabled="busy">{{t('Accept invitation','Принять приглашение')}}<Icon name="ArrowRight" :size="17"/></button><template v-else><RouterLink class="btn primary full" to="/register">{{t('Create your account','Создать аккаунт')}}</RouterLink><RouterLink class="btn secondary full mt-sm" to="/login">{{t('I already have an account','У меня уже есть аккаунт')}}</RouterLink></template></template><p v-if="error" class="notice error-notice" role="alert">{{error}}</p></template>
  <template v-else><span class="eyebrow">{{register?t('LET’S GET YOU SET UP','НАЧНЁМ РАБОТУ'):t('WELCOME BACK','С ВОЗВРАЩЕНИЕМ')}}</span><h2>{{forgot?t('Reset your password','Сбросить пароль'):reset?t('Choose a new password','Выберите новый пароль'):register?t('Create your account','Создать аккаунт'):t('Your next insight awaits.','Новые выводы ждут вас.')}}</h2><p class="muted">{{forgot?t('We’ll email you a secure link.','Мы отправим защищённую ссылку на вашу почту.'):register?t('A few details, then we’ll get to know your business.','Пара деталей — и познакомимся с вашим бизнесом.'):t('Sign in to your business intelligence workspace.','Войдите в ваше пространство бизнес-аналитики.')}}</p>
  <form @submit.prevent="submit" class="form-stack"><label v-if="register&&!forgot">{{t('Your name','Ваше имя')}}<input v-model="name" name="name" autocomplete="name" :placeholder="t('Alex Morgan','Александр Иванов')" required maxlength="100"></label><label v-if="!reset">{{t('Work email','Рабочая почта')}}<input v-model="email" name="email" type="email" autocomplete="email" placeholder="you@company.com" required maxlength="254"></label><label v-if="!forgot">{{t('Password','Пароль')}}<input v-model="password" name="password" type="password" :autocomplete="register||reset?'new-password':'current-password'" :placeholder="t('At least 10 characters','Не менее 10 символов')" required minlength="10" maxlength="200"></label><div v-if="error" class="notice error-notice" role="alert">{{error}}</div><div v-if="success" class="notice success-notice" role="status">{{success}}</div><button class="btn primary full large-btn" :disabled="busy"><Icon v-if="busy" name="LoaderCircle" class="spin" :size="17"/>{{forgot?t('Send reset link','Отправить ссылку'):reset?t('Save password','Сохранить пароль'):register?t('Create account','Создать аккаунт'):t('Sign in','Войти')}}<Icon v-if="!busy" name="ArrowRight" :size="17"/></button></form><button v-if="!register&&!reset" class="text-link center mt-sm" @click="forgot=!forgot">{{forgot?t('Back to sign in','Вернуться ко входу'):t('Forgot your password?','Забыли пароль?')}}</button><p v-if="!reset&&!forgot" class="auth-switch">{{register?t('Already have an account?','Уже есть аккаунт?'):t('New to SignalDesk?','Впервые в SignalDesk?')}} <RouterLink :to="register?'/login':'/register'">{{register?t('Sign in','Войти'):t('Create an account','Создать аккаунт')}}</RouterLink></p><p class="auth-privacy"><Icon name="LockKeyhole" :size="13"/>{{t('Your business context stays in your workspace.','Контекст вашего бизнеса остаётся в вашем пространстве.')}}</p></template>
</section></div></template>
